(() => {
  "use strict";
  const SESSION_KEY = "ielts-cloze-cloud-session-v1";
  const API = location.hostname.endsWith("github.io") ? "https://ielts-cloze-lab.woodsy-mint-9620.chatgpt.site" : "";
  let session = readSession(), timer = null, syncing = false;
  function readSession(){try{const s=JSON.parse(localStorage.getItem(SESSION_KEY)||"null");return s&&typeof s.vaultId==="string"&&typeof s.token==="string"?s:null}catch{return null}}
  function saveSession(value){session=value;if(value)localStorage.setItem(SESSION_KEY,JSON.stringify(value));else localStorage.removeItem(SESSION_KEY)}
  async function request(path,options={}){const headers=Object.assign({"content-type":"application/json"},options.headers||{});if(session?.token)headers.authorization=`Bearer ${session.token}`;const response=await fetch(API+path,Object.assign({},options,{headers})),data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||"云端连接失败。");return data}
  function esc(value){const n=document.createElement("span");n.textContent=value;return n.innerHTML}
  function note(value,bad=false){const n=document.getElementById("cloudMessage");if(n){n.textContent=value||"";n.classList.toggle("bad",bad)}}
  function current(){return window.IELTSCloud?.getState?.()||null}
  function refresh(){const status=document.getElementById("cloudStatus"),create=document.getElementById("cloudCreate"),login=document.getElementById("cloudLogin"),connected=document.getElementById("cloudConnected"),button=document.getElementById("cloudSyncButton");if(!status)return;if(session){status.innerHTML=`<span class="cloud-dot online"></span><div><b>已连接云端词库</b><small>同步 ID：<code>${esc(session.vaultId)}</code></small></div>`;create.hidden=true;login.hidden=true;connected.hidden=false;button?.classList.add("connected")}else{status.innerHTML='<span class="cloud-dot"></span><div><b>尚未连接</b><small>开启后可在任何设备继续学习。</small></div>';create.hidden=false;login.hidden=false;connected.hidden=true;button?.classList.remove("connected")}}
  function merge(local,remote){if(!local)return remote;if(!remote)return local;const cards=new Map();[...(remote.cards||[]),...(local.cards||[])].forEach(c=>{const key=String(c.id||c.word||"").toLowerCase(),old=cards.get(key);if(!old||Number(c.updatedAt||0)>=Number(old.updatedAt||0))cards.set(key,c)});const newest=Number(local.updatedAt||0)>=Number(remote.updatedAt||0)?local:remote;return Object.assign({},remote,local,newest,{cards:[...cards.values()],updatedAt:Date.now()})}
  async function register(){const passphrase=document.getElementById("cloudNewPass").value,state=current();if(!state)return note("学习页面仍在初始化，请稍后再试。",true);if(passphrase.length<10)return note("同步口令至少需要 10 个字符。",true);note("正在创建私有云端词库…");try{const d=await request("/api/v1/register",{method:"POST",body:JSON.stringify({passphrase,state})});saveSession({vaultId:d.vaultId,token:d.token});document.getElementById("cloudNewPass").value="";refresh();note("已开启。请保存上方同步 ID；新设备需要它和同一组口令。")}catch(e){note(e.message,true)}}
  async function login(){const vaultId=document.getElementById("cloudVaultId").value.trim(),passphrase=document.getElementById("cloudPass").value;if(!vaultId||passphrase.length<10)return note("请输入同步 ID 和至少 10 个字符的口令。",true);note("正在连接云端词库…");try{const d=await request("/api/v1/login",{method:"POST",body:JSON.stringify({vaultId,passphrase})});saveSession({vaultId:d.vaultId,token:d.token});const state=merge(current(),d.state);window.IELTSCloud.replaceState(state);await request("/api/v1/state",{method:"PUT",body:JSON.stringify({state})});document.getElementById("cloudPass").value="";refresh();note("已连接并合并本设备词库。之后的修改会自动同步。")}catch(e){note(e.message,true)}}
  async function pull(){if(!session)return;note("正在获取云端词库…");try{const d=await request("/api/v1/state",{method:"GET"}),state=merge(current(),d.state);window.IELTSCloud.replaceState(state);await request("/api/v1/state",{method:"PUT",body:JSON.stringify({state})});note("同步完成。")}catch(e){if(/会话已失效/.test(e.message))saveSession(null);refresh();note(e.message,true)}}
  async function push(state){if(!session||syncing||!state)return;syncing=true;try{await request("/api/v1/state",{method:"PUT",body:JSON.stringify({state})})}catch(e){if(/会话已失效/.test(e.message))saveSession(null);console.warn("Cloud sync paused:",e.message)}finally{syncing=false;refresh()}}
  function queue(state){if(!session)return;clearTimeout(timer);timer=setTimeout(()=>push(state),700)}
  function disconnect(){saveSession(null);refresh();note("已只在本设备断开；云端词库仍会保留。")} 
  function mount(){const holder=document.querySelector(".top-actions")||document.querySelector(".topbar");if(!holder||document.getElementById("cloudSyncButton"))return;const button=document.createElement("button");button.id="cloudSyncButton";button.className="cloud-sync-button";button.type="button";button.innerHTML='<span class="cloud-dot"></span><span>云端词库</span>';button.onclick=()=>{refresh();note("");document.getElementById("cloudSyncDialog")?.showModal?.()};holder.append(button);const dialog=document.createElement("dialog");dialog.id="cloudSyncDialog";dialog.className="cloud-dialog";dialog.innerHTML='<form method="dialog" class="cloud-sheet"><button class="cloud-close" value="cancel" aria-label="关闭云端同步">×</button><p class="eyebrow">CLOUD VAULT</p><h2>跨设备同步词库</h2><p class="cloud-copy">单词、错题本、收藏与复习进度会保存到你的私有云端词库。同步口令只用于验证，不会被保存。</p><div id="cloudStatus" class="cloud-status"></div><section id="cloudCreate" class="cloud-section"><h3>首次使用</h3><label>设置同步口令<input id="cloudNewPass" type="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="至少 10 个字符"></label><button id="cloudCreateBtn" class="primary" type="button">开启云端同步</button></section><section id="cloudLogin" class="cloud-section"><h3>在新设备接入</h3><label>同步 ID<input id="cloudVaultId" autocomplete="username" placeholder="vault_…"></label><label>同步口令<input id="cloudPass" type="password" minlength="10" maxlength="128" autocomplete="current-password" placeholder="输入同一组口令"></label><button id="cloudLoginBtn" class="soft" type="button">连接已有词库</button></section><div id="cloudConnected" class="cloud-connected" hidden><button id="cloudNowBtn" class="soft" type="button">立即同步</button><button id="cloudDisconnectBtn" class="text-button" type="button">仅断开本设备</button></div><p id="cloudMessage" class="cloud-message" role="status"></p></form>';document.body.append(dialog);document.getElementById("cloudCreateBtn").onclick=register;document.getElementById("cloudLoginBtn").onclick=login;document.getElementById("cloudNowBtn").onclick=pull;document.getElementById("cloudDisconnectBtn").onclick=disconnect;refresh()}
  window.IELTSCloud=Object.assign(window.IELTSCloud||{},{queue,start:mount});
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",mount,{once:true});else mount();
})();
